using System;
using System.Drawing;
using System.IO;

namespace MobileOneMedia.DevDeckStudio
{
    public static class AgencyAssets
    {
        private static Image _cachedLogo = null;
        private static MemoryStream _logoStream = null;
        public const string LOGO_BASE64 = "";

        public static Image GetLogo()
        {
            if (_cachedLogo != null) return _cachedLogo;
            try
            {
                byte[] data = Convert.FromBase64String(LOGO_BASE64);
                _logoStream = new MemoryStream(data);
                _cachedLogo = Image.FromStream(_logoStream);
                return _cachedLogo;
            }
            catch
            {
                return null;
            }
        }
    }
}